"""Alert model."""

from datetime import datetime

from app.extensions import db


class Alert(db.Model):
    """Alert generated by sepsis assessment."""

    __tablename__ = "alerts"

    id = db.Column(db.Integer, primary_key=True)
    patient_id = db.Column(
        db.Integer, db.ForeignKey("patients.id"), nullable=False, index=True
    )
    episode_id = db.Column(
        db.Integer, db.ForeignKey("sepsis_episodes.id"), nullable=True
    )
    message = db.Column(db.String(255), nullable=False)
    severity = db.Column(db.String(20), default="medium")  # low, medium, high, critical
    acknowledged = db.Column(db.Boolean, default=False)
    acknowledged_by = db.Column(db.Integer, db.ForeignKey("users.id"), nullable=True)
    acknowledged_at = db.Column(db.DateTime)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

    patient = db.relationship("Patient", back_populates="alerts")
    episode = db.relationship("SepsisEpisode", back_populates="alerts")
